import { tags } from "typia";

/**
 * Access token used for authentication validation across the shopping mall
 * platform. This token represents the current authenticated session and
 * contains user identity, permissions, and expiration information embedded
 * within the JWT structure.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAccessToken = {
  /**
   * JWT access token for authentication validation. Must be a valid JWT token
   * issued by the platform's authentication system with proper signature and
   * claims.
   */
  token: string &
    tags.Pattern<"^[A-Za-z0-9-_]+\\.[A-Za-z0-9-_]+\\.[A-Za-z0-9-_]+$">;
};
